				pokePara.SetCondition((Condition)i, (byte)Mathf.Clamp(flavor[i] + condition, 0, 255));
				ConditionParam.AddCondition[i] = flavor[i];
				ConditionParam.NowCondition[i] = pokePara.GetCondition((Condition)i);
			}

			byte fur = pokePara.GetCondition(Condition.FUR);
			ConditionParam.PrevCondition[5] = fur;
			int newFur = Mathf.Clamp(poffin.Taste + fur, 0, 255);
			pokePara.SetCondition(Condition.FUR, (byte)newFur);
			ConditionParam.AddCondition[5] = poffin.Taste;
			ConditionParam.NowCondition[5] = (byte)newFur;
		}
